(9059, 105, 4, 'ТАКСИ [city_1_im] [city_2_im]'),
(9060, 106, 4, 'НАДЕЖНОЕ И ДОСТУПНОЕ ТАКСИ  ИЗ [city_1_rod] В [city_2_vin] ПО ЦЕНЕ НА 25% НИЖЕ РЫНОЧНЫХ. СПЕШИТЕ ЗАКАЗАТЬ ТАКСИ ПО НИЗКИМ ЦЕНАМ'),
